#!/usr/bin/env python3
"""Check every build-generated byte pin against ELDEN RING 2.7.2.0, where the runtime will look.

    uv run --with capstone python3 scripts/audit-1172-pins.py [--all] [--map <address_map_1170.rs>]

Every `PrologueSpec` in `crates/*/build.rs` names the image its pin was read from and the address
in that image. At runtime the pin is compared against the running game at the address the crate
resolves, which on 2.7.2.0 is:

* `Image::EldenRing` (1.16.2): the 1.16.2 function entry carried through the address map
  (`VERIFIED_1162_TO_1170`, or `DETOUR_SAFE_1162_TO_1170` for a detour), then 1.17.0 -> 1.17.1 by
  the `+0x70` rule and 1.17.1 -> 2.7.2.0 through `docs/recon/carry-1171-to-1172.tsv`; a pin in the
  middle of a function rides on its containing function's entry plus the same offset, which is
  what `resolve_call_site_rva` does;
* `Image::EldenRing1170`: the 1.17.0 address carried the same two steps;
* `Image::EldenRing1171`: the 1.17.1 address carried one step.

It reads the bytes at the 1.17.1 and the 2.7.2.0 answer from the flat de-Arxan'd images in the main
checkout and compares them with the pin twice: exactly, and under the generator's mask (only a
RIP-relative displacement is ignored; rel32 branch targets are compared). A pin that matched on
1.17.1 and does not on 2.7.2.0 is a feature 2.7.2.0 disarms. Read-only; prints one line per spec
and the disassembly of every mismatch.

The address map is read from a generated `address_map_1170.rs` (any er-game-base build of this
tree), because the build script that produces it is the definition of what the runtime holds.
`--map` names one; otherwise the newest under this checkout's or the main checkout's `target/`.
"""

import bisect
import glob
import os
import re
import struct
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
BASE = 0x1_4000_0000
TEXT_END = 0x29A5800
BOUNDARY_1171 = 0xAFEFE9
IMAGE_NAMES = {
    "1162": "eldenring-deobf.bin",
    "1170": "eldenring-deobf-1.17.bin",
    "1171": "eldenring-deobf-1.17.1.bin",
    "1172": "eldenring-deobf-1.17.2.bin",
}


def image_dir() -> Path:
    env = os.environ.get("ER_DEOBF_DIR")
    if env:
        return Path(env)
    for candidate in (REPO, *REPO.parents):
        if (candidate / IMAGE_NAMES["1172"]).exists():
            return candidate
    sys.exit("no eldenring-deobf-1.17.2.bin above this checkout; set ER_DEOBF_DIR")


_IMAGES: dict[str, bytes] = {}


def image(tag: str) -> bytes:
    if tag not in _IMAGES:
        _IMAGES[tag] = (image_dir() / IMAGE_NAMES[tag]).read_bytes()
    return _IMAGES[tag]


def find_map(explicit: str | None) -> Path:
    if explicit:
        return Path(explicit)
    roots = [REPO, *[p for p in REPO.parents if (p / "Cargo.toml").exists()]]
    found = []
    for root in roots:
        found += glob.glob(str(root / "target/**/er-game-base-*/out/address_map_1170.rs"), recursive=True)
    found = [f for f in found if "CARRY_1171_TO_1172" in Path(f).read_text()]
    if not found:
        sys.exit("no generated address_map_1170.rs with the 2.7.2.0 carry; build er-game-base or pass --map")
    return Path(max(found, key=os.path.getmtime))


def table(src: str, name: str) -> list[tuple[int, ...]]:
    m = re.search(name + r"\s*:\s*\[[^\]]*\]\s*=\s*\[(.*?)\];", src, re.S)
    if not m:
        sys.exit(f"{name} not found in the generated map")
    rows = []
    for t in re.finditer(r"\(([^()]*)\)", m.group(1)):
        parts = [p.strip() for p in t.group(1).split(",") if p.strip()]
        rows.append(tuple(int(p.replace("_", ""), 0) for p in parts))
    return rows


class AddressModel:
    def __init__(self, map_rs: Path):
        src = map_rs.read_text()
        self.verified = dict(table(src, "VERIFIED_1162_TO_1170"))
        self.detour = dict(table(src, "DETOUR_SAFE_1162_TO_1170"))
        self.carry = table(src, "CARRY_1171_TO_1172")
        self.carry_lo = [r[0] for r in self.carry]

    @staticmethod
    def to_1171(rva: int) -> int:
        return rva + 0x70 if BOUNDARY_1171 <= rva < TEXT_END else rva

    def to_1172(self, rva: int) -> int | None:
        at = bisect.bisect_right(self.carry_lo, rva) - 1
        if at < 0:
            return None
        lo, hi, delta = self.carry[at]
        return rva + delta if lo <= rva < hi else None


def pdata(tag: str) -> list[tuple[int, int]]:
    img = image(tag)
    pe = struct.unpack_from("<I", img, 0x3C)[0]
    rva, size = struct.unpack_from("<II", img, pe + 0x18 + 0x70 + 3 * 8)
    out = set()
    for off in range(0, size - 11, 12):
        begin, end, _ = struct.unpack_from("<III", img, rva + off)
        if 0 < begin < end:
            out.add((begin, end))
    return sorted(out)


_PDATA: dict[str, list[tuple[int, int]]] = {}


def containing(tag: str, rva: int) -> tuple[int, int] | None:
    if tag not in _PDATA:
        _PDATA[tag] = pdata(tag)
    recs = _PDATA[tag]
    at = bisect.bisect_right(recs, (rva, 1 << 40)) - 1
    if at >= 0 and recs[at][0] <= rva < recs[at][1]:
        return recs[at]
    return None


def rip_mask(code: bytes, va: int) -> bytes:
    import capstone

    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
    md.detail = True
    mask = bytearray(b"\xff" * len(code))
    for ins in md.disasm(code, va):
        for op in ins.operands:
            if op.type == capstone.x86.X86_OP_MEM and op.mem.base == capstone.x86.X86_REG_RIP:
                start = ins.address - va + ins.disp_offset
                for k in range(ins.disp_size):
                    if start + k < len(mask):
                        mask[start + k] = 0
    return bytes(mask)


def masked_eq(a: bytes, b: bytes, mask: bytes) -> bool:
    return len(a) == len(b) and all((x & m) == (y & m) for x, y, m in zip(a, b, mask))


def disasm(code: bytes, va: int) -> list[str]:
    import capstone

    md = capstone.Cs(capstone.CS_ARCH_X86, capstone.CS_MODE_64)
    return [f"{i.address:#x}: {i.bytes.hex(' '):<30} {i.mnemonic} {i.op_str}" for i in md.disasm(code, va)]


# ---------------------------------------------------------------------------------------------
# build.rs parsing
# ---------------------------------------------------------------------------------------------

CONST_RE = re.compile(r"^\s*(?:pub(?:\([^)]*\))?\s+)?const\s+(\w+)\s*:\s*[iu](?:64|32|size)\s*=\s*([^;]+);", re.M)
SPEC_RE = re.compile(r"PrologueSpec\s*\{(.*?)\n\s*\}", re.S)


def rust_expr(expr: str) -> str:
    """A Rust integer expression as Python: digit separators and type suffixes dropped."""
    expr = re.sub(r"\b(0x[0-9a-fA-F_]+|\d[\d_]*)(?:[iu](?:8|16|32|64|size))?\b",
                  lambda m: m.group(1).replace("_", ""), expr)
    return expr.replace(" as u64", "").replace(" as i64", "").replace(" as usize", "")


def eval_consts(src: str) -> dict[str, int]:
    env: dict[str, int] = {}
    pending = CONST_RE.findall(src)
    for _ in range(4):
        for name, expr in pending:
            if name in env:
                continue
            try:
                env[name] = int(eval(rust_expr(expr), {}, dict(env)))
            except Exception:
                pass
    return env


INCLUDE_RE = re.compile(r'include!\(concat!\(env!\("CARGO_MANIFEST_DIR"\),\s*"([^"]+)"\)\)')


def parse_specs(path: Path):
    src = path.read_text()
    # Constants a build script pulls in from its crate (`patch_sites.rs` and the like) are part of
    # the address arithmetic, so they are read along with it.
    included = "".join(
        (path.parent / rel.lstrip("/")).read_text()
        for rel in INCLUDE_RE.findall(src)
        if (path.parent / rel.lstrip("/")).exists()
    )
    env = eval_consts(included + "\n" + src)
    for m in SPEC_RE.finditer(src):
        body = m.group(1)
        name = re.search(r'name:\s*"(\w+)"', body).group(1)
        img = re.search(r"image:\s*Image::(\w+)", body).group(1)
        va_expr = re.search(r"va:\s*([^,\n]+),", body).group(1).strip()
        pin_m = re.search(r"pin:\s*&\[(.*?)\]", body, re.S)
        pin = bytes(int(x, 16) for x in re.findall(r"0x([0-9A-Fa-f]{1,2})\b", pin_m.group(1))) if pin_m else b""
        try:
            va = int(eval(rust_expr(va_expr), {}, dict(env)))
        except Exception:
            va = None
        line = src[: m.start()].count("\n") + 1
        yield {"crate": path.parent.name, "line": line, "name": name, "image": img,
               "va_expr": va_expr, "va": va, "pin": pin}


# ---------------------------------------------------------------------------------------------


def place(spec, model: AddressModel):
    """(rva on 1.17.1, rva on 2.7.2.0, how) for a spec, or Nones with the reason."""
    rva = spec["va"] - BASE
    img = spec["image"]
    if img == "EldenRing1171":
        return rva, model.to_1172(rva), "carry 1.17.1"
    if img == "EldenRing1170":
        r1 = model.to_1171(rva)
        return r1, model.to_1172(r1), "carry 1.17.0"
    if img == "EldenRing" and spec.get("detour"):
        # `resolve_detour_address` on the entry itself: the detour table or nothing.
        if rva not in model.detour:
            why = "call-only row" if rva in model.verified else "no row"
            return None, None, f"1.16.2 {rva:#x}: not in DETOUR_SAFE ({why})"
        d0 = model.detour[rva]
        r1 = model.to_1171(d0)
        return r1, model.to_1172(r1), f"1.16.2 detour {rva:#x}"
    if img == "EldenRing":
        rec = containing("1162", rva)
        entry = rec[0] if rec else None
        notes = []
        if rva in model.verified:
            entry = rva
        elif entry is None or entry not in model.verified:
            # A chained `.pdata` record: walk back to the nearest mapped entry before the site.
            keys = sorted(model.verified)
            at = bisect.bisect_right(keys, rva) - 1
            if at >= 0 and rva - keys[at] < 0x4000:
                entry = keys[at]
                notes.append(f"anchored on nearest mapped entry {entry:#x}")
            else:
                return None, None, f"1.16.2 {rva:#x}: no mapped entry"
        offset = rva - entry
        d0 = model.verified[entry]
        r1 = model.to_1171(d0) + offset
        carried = model.to_1172(model.to_1171(d0))
        r2 = None if carried is None else carried + offset
        detour = "detour-safe" if entry in model.detour else "call-only"
        how = f"1.16.2 fn {entry:#x}+{offset:#x} ({detour})" + (f"; {notes[0]}" if notes else "")
        return r1, r2, how
    return None, None, f"image {img} not a game image"


SEAM_RE = re.compile(
    r'MapSeam\s*\{\s*name:\s*"([^"]+)",\s*rva:\s*(0x[0-9a-fA-F_]+),\s*prologue:\s*&\[(.*?)\]', re.S
)


def parse_seams(path: Path):
    """Hand-written `MapSeam`s: a 1.16.2 rva and the prologue `verify_seam` compares, unmasked."""
    src = path.read_text()
    for m in SEAM_RE.finditer(src):
        pin = bytes(int(x, 16) for x in re.findall(r"0x([0-9A-Fa-f]{1,2})\b", m.group(3)))
        rva = int(m.group(2).replace("_", ""), 16)
        line = src[: m.start()].count("\n") + 1
        yield {"crate": f"{path.parent.parent.name}/{path.name}", "line": line, "name": m.group(1),
               "image": "EldenRing", "va_expr": m.group(2), "va": BASE + rva, "pin": pin,
               "exact_only": True, "detour": True}


def main() -> None:
    args = sys.argv[1:]
    show_all = "--all" in args
    explicit = args[args.index("--map") + 1] if "--map" in args else None
    model = AddressModel(find_map(explicit))
    specs = []
    for path in sorted(REPO.glob("crates/*/build.rs")):
        specs += list(parse_specs(path))
    for path in sorted(REPO.glob("crates/*/src/**/*.rs")):
        if "MapSeam {" in path.read_text():
            specs += list(parse_seams(path))
    bad = 0
    for s in specs:
        if s["image"] == "Ersc201":
            continue
        if s["va"] is None:
            print(f"?? {s['crate']}:{s['line']} {s['name']}: va `{s['va_expr']}` not evaluated")
            bad += 1
            continue
        r1, r2, how = place(s, model)
        pin = s["pin"]
        n = len(pin)
        if r1 is None:
            print(f"UNPLACED {s['crate']}:{s['line']} {s['name']} [{s['image']}]: {how}")
            bad += 1
            continue
        b1 = image("1171")[r1 : r1 + n]
        # A hand-written seam is compared with `!=` at runtime, so its mask ignores nothing.
        mask = b"\xff" * n if s.get("exact_only") else rip_mask(pin, s["va"])
        m1x, m1m = b1 == pin, masked_eq(b1, pin, mask)
        if r2 is None:
            verdict = "REFUSED-2720"
            m2x = m2m = False
            b2 = b""
        else:
            b2 = image("1172")[r2 : r2 + n]
            m2x, m2m = b2 == pin, masked_eq(b2, pin, mask)
            verdict = "OK" if m2m else ("REGRESSION" if m1m else "BAD-BOTH")
        if verdict != "OK":
            bad += 1
        if verdict != "OK" or show_all:
            r2s = "none" if r2 is None else f"{BASE + r2:#x}"
            print(f"{verdict:12} {s['crate']}:{s['line']} {s['name']} [{s['image']} {s['va']:#x}] "
                  f"1171={BASE + r1:#x} exact={m1x} masked={m1m} | 2720={r2s} exact={m2x} masked={m2m} | {how}")
            if verdict != "OK":
                print("      pin : " + pin.hex(" "))
                print("      1171: " + b1.hex(" "))
                if b2:
                    print("      2720: " + b2.hex(" "))
                    for line in disasm(b2, BASE + r2):
                        print("        " + line)
    print(f"{len(specs)} specs, {bad} not OK on 2.7.2.0")


if __name__ == "__main__":
    main()
